const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

const cityPriority = cfg.cityPriority || {roscrea:1, athlone:2, templemore:3, birr:3, nenagh:3};
const areaWords = (cfg.areaKeywords || Object.keys(cityPriority)).map(s => String(s).toLowerCase());
const includeNearby = cfg.includeOptionalNearby !== false;

function detectCity(text) {
  const t = String(text || '').toLowerCase();
  // priority order check for roscrea first
  const ordered = Object.entries(cityPriority).sort((a,b)=>a[1]-b[1]).map(([k])=>k);
  for (const city of ordered) {
    if (t.includes(city)) return city;
  }
  return '';
}

function inArea(text) {
  const t = String(text || '').toLowerCase();
  return areaWords.some(w => t.includes(w));
}

function parsePriceToMonthly(priceText) {
  const t = String(priceText || '');
  const m = t.replace(/,/g, '').match(/€\s?(\d+(?:\.\d+)?)/);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  if (/week/i.test(t)) return Math.round(n * 52 / 12);
  return Math.round(n);
}

function bedsNum(v) {
  const m = String(v || '').match(/(\d+)/);
  return m ? Number(m[1]) : 0;
}

function htmlOf(item) {
  const j = item.json;
  if (typeof j === 'string') return j;
  return j.data || j.body || j.html || '';
}

function extractDaft(html, sourceUrl, sourceName, sourcePriority, sourceCity) {
  const match = String(html).match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
  if (!match) return [];
  let data; try { data = JSON.parse(match[1]); } catch (e) { return []; }
  const list = (((data || {}).props || {}).pageProps || {}).listings || [];
  const out = [];
  for (const row of list) {
    const L = row.listing || row;
    if (!L || !L.id) continue;
    const title = L.title || '';
    const path = L.seoFriendlyPath || '';
    const url = path ? `https://www.daft.ie${path}` : `https://www.daft.ie/for-rent/${L.id}`;
    const blob = `${title} ${path} ${sourceUrl} ${sourceCity||''}`;
    if (!inArea(blob)) continue;
    const city = detectCity(blob) || String(sourceCity||'').toLowerCase();
    const priority = cityPriority[city] || Number(sourcePriority) || 9;
    if (!includeNearby && priority >= 3) continue;

    const monthly = parsePriceToMonthly(L.price);
    const beds = bedsNum(L.numBedrooms);
    const minBeds = Number(cfg.minBeds || 0);
    if (minBeds > 0 && beds > 0 && beds < minBeds) continue;
    if (Number(cfg.maxMonthlyEuro) > 0 && monthly && monthly > Number(cfg.maxMonthlyEuro)) continue;

    out.push({
      id: `daft-${L.id}`,
      source: sourceName || 'daft',
      city,
      priority,
      title,
      price: L.price || '',
      monthly,
      beds: L.numBedrooms || '',
      baths: L.numBathrooms || '',
      propertyType: L.propertyType || '',
      seller: (L.seller && L.seller.name) || '',
      sellerType: (L.seller && L.seller.sellerType) || '',
      url,
      detectedAtMs: Date.now()
    });
  }
  return out;
}

function extractMyHome(html, sourceName, sourcePriority, sourceCity) {
  const text = String(html);
  if (/No homes listed here yet/i.test(text)) return [];
  const city = detectCity(`${text.slice(0,3000)} ${sourceCity||''}`) || String(sourceCity||'roscrea').toLowerCase();
  const priority = cityPriority[city] || Number(sourcePriority) || 1;
  if (!includeNearby && priority >= 3) return [];
  const abs = [...text.matchAll(/https?:\/\/www\.myhome\.ie\/[^"'\\\s<>]+/g)].map(m => m[0].replace(/&amp;/g,'&'));
  const rel = [...text.matchAll(/href=\"(\/rentals\/[^\"]+)\"/g)].map(m => 'https://www.myhome.ie' + m[1].replace(/&amp;/g,'&'));
  const all = [...new Set([...abs, ...rel])]
    .filter(u => !/house-to-rent-in-roscrea|apartment-to-rent-in-roscrea/i.test(u))
    .filter(u => /\/\d{4,}/.test(u) || /property|residential|rental/i.test(u));
  return all.slice(0, 30).map(url => ({
    id: `myhome-${url}`,
    source: sourceName || 'myhome',
    city,
    priority,
    title: `MyHome rental (${city})`,
    price: '',
    monthly: null,
    beds: '',
    baths: '',
    propertyType: '',
    seller: '',
    sellerType: '',
    url,
    detectedAtMs: Date.now()
  }));
}

const urlItems = $('Split Sources').all();
const found = [];
const batch = new Set();
for (let i = 0; i < items.length; i++) {
  const meta = (urlItems[i] && urlItems[i].json) || {};
  const html = htmlOf(items[i]);
  const sourceUrl = meta.url || '';
  const source = meta.source || 'unknown';
  const sourcePriority = meta.priority;
  const sourceCity = meta.city || '';
  let list = [];
  if (String(source).startsWith('daft')) list = extractDaft(html, sourceUrl, source, sourcePriority, sourceCity);
  else if (String(source).startsWith('myhome')) list = extractMyHome(html, source, sourcePriority, sourceCity);
  for (const L of list) {
    if (batch.has(L.id) || staticData.seen[L.id]) continue;
    batch.add(L.id);
    found.push({ json: { ...cfg, ...L } });
  }
}
// Roscrea first in telegram order
found.sort((a,b)=> (a.json.priority||9)-(b.json.priority||9));
return found;

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const cfg = $('Config').first().json;
const candidate = $('Has Candidates?').item.json;
const htmlRaw = items[0].json;
const html = typeof htmlRaw === 'string' ? htmlRaw : (htmlRaw.data || htmlRaw.body || htmlRaw.html || '');

function unavailable(html) {
  const t = String(html || '');
  if (!t || t.length < 200) return true;
  if (/no longer available|this ad has been removed|ad has expired|property is no longer available|removed by the advertiser/i.test(t)) return true;
  const m = t.match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
  if (m) {
    try {
      const data = JSON.parse(m[1]);
      const listing = (((data || {}).props || {}).pageProps || {}).listing;
      if (listing && listing.state && String(listing.state).toUpperCase() !== 'PUBLISHED') return true;
      if (listing) {
        candidate.title = listing.title || candidate.title;
        candidate.price = listing.price || candidate.price;
        candidate.seller = (listing.seller && listing.seller.name) || candidate.seller;
        candidate.beds = listing.numBedrooms || candidate.beds;
        candidate.propertyType = listing.propertyType || candidate.propertyType;
        if (listing.seoFriendlyPath) candidate.url = `https://www.daft.ie${listing.seoFriendlyPath}`;
        const blob = `${candidate.title} ${candidate.url}`;
        const keys = Object.keys(cfg.cityPriority || {roscrea:1,athlone:2});
        for (const city of keys.sort((a,b)=>(cfg.cityPriority[a]-cfg.cityPriority[b]))) {
          if (blob.toLowerCase().includes(city)) { candidate.city = city; candidate.priority = cfg.cityPriority[city]; break; }
        }
      }
    } catch (e) {}
  }
  return false;
}

if (unavailable(html)) {
  staticData.seen[candidate.id] = Date.now();
  return [];
}

staticData.seen[candidate.id] = Date.now();
const entries = Object.entries(staticData.seen).sort((a,b)=>b[1]-a[1]);
if (entries.length > 1000) staticData.seen = Object.fromEntries(entries.slice(0,1000));

function monthly(priceText) {
  const t = String(priceText || '');
  const m = t.replace(/,/g,'').match(/€\s?(\d+(?:\.\d+)?)/);
  if (!m) return candidate.monthly || null;
  const n = Number(m[1]);
  if (/week/i.test(t)) return Math.round(n * 52 / 12);
  return Math.round(n);
}

const mon = monthly(candidate.price);
const detectedAtMs = candidate.detectedAtMs || Date.now();
const ageSec = Math.max(0, Math.round((Date.now() - detectedAtMs) / 1000));
const detected = new Date(detectedAtMs).toLocaleTimeString('en-IE', { hour12: false, timeZone: 'Europe/Dublin' });
const ageLabel = ageSec < 60 ? `${ageSec} seconds ago` : `${Math.round(ageSec/60)} min ago`;
const city = (candidate.city || 'unknown');
const priority = Number(candidate.priority || 9);
const badge = priority === 1 ? '🔥 PRIORITY: ROSCREA' : priority === 2 ? '⭐ ATHLONE' : '🟡 NEARBY — check sports for son';
const sportsNote = priority <= 2
  ? 'Family fit: same-town sports section possible'
  : '⚠ Nearby town: confirm sports section before chasing hard';

const text = [
  `🚨 NEW PROPERTY`,
  badge,
  ``,
  `🏠 ${candidate.beds || '? Bed'} ${candidate.propertyType || 'Property'}`,
  `📍 ${candidate.title}`,
  `🏷 City: ${city}`,
  `💶 ${candidate.price || 'See ad'}${mon ? ` (~€${mon}/mo)` : ''}`,
  `🕐 detected: ${detected}`,
  `🟢 NEW — ${ageLabel}`,
  `📡 ${candidate.source}`,
  `✅ LIVE verified`,
  sportsNote,
  ``,
  `🔗 ${candidate.url}`,
  ``,
  `ACTION:`,
  `1) Open`,
  `2) Call if phone visible`,
  `3) Else Enquire NOW`,
  ``,
  `Script:`,
  `Hi, I'm interested in this rental.`,
  `Is it still available for a viewing this week?`
].join('\n');

return [{
  json: {
    ...candidate,
    city,
    priority,
    monthly: mon,
    telegramChatId: cfg.telegramChatId,
    sheetId: cfg.sheetId,
    status: 'available',
    foundAt: new Date().toISOString(),
    text
  }
}];
